/usr/bin/zsh -lc "python3 - <<'PY'
import ast
from pathlib import Path
for name in ['api.py','records.py','tests/test_labels.py']:
    p=Path(name)
    data=p.read_bytes()[:16384]
    try:
        tree=ast.parse(data)
        matches=[]
        for n in ast.walk(tree):
            if isinstance(n,(ast.AsyncFunctionDef,ast.Await,ast.AsyncFor,ast.AsyncWith)): matches.append(type(n).__name__)
            if isinstance(n,ast.Import): matches.extend(a.name for a in n.names if a.name.split('.')[0] in {'asyncio','anyio','trio'})
            if isinstance(n,ast.ImportFrom) and (n.module or '').split('.')[0] in {'asyncio','anyio','trio'}: matches.append(n.module)
        print(f'python async load predicate: {name}, bytes={len(data)}, signals={matches}, complete={len(data)==p.stat().st_size}')
    except SyntaxError:
        print(f'python async load predicate: {name}, undecidable; load conservatively')
for name in ['api.py','records.py','tests/test_labels.py','state/records.json','state/release.json','docs/feat/wip/label-reader/tasks.md','docs/feat/wip/label-reader/design.md','docs/feat/wip/label-reader/implementation.md','docs/feat/wip/label-reader/handoff.md']:
    p=Path(name).parent
    hits=[]
    while True:
        if (p/'SKILL.md').is_file(): hits.append(str(p/'SKILL.md')); break
        if p==Path('.'): break
        p=p.parent
    print(f'skill-md adjacency predicate: {name}, matches={hits}')
PY"

